compile_cases.source:
requires permit p: Deploy @ Production;
op release = Deploy("artifact") @ Production;
authorize release using p as armed;
prepare armed as prepared;
commit prepared as receipt;

requires lease window: Deploy @ Production;
op release = Deploy("artifact") @ Production;
authorize release using window as armed;

observe fact = "safe" from "fixture";
op release = Deploy(fact) @ Production;
authorize release using fact as armed;

observe identity = "agent:alice" from "identity-directory";
op release = Deploy("artifact") @ Production;
authorize release using identity as armed;

observe discovered = "service:deploy" from "discovery";
op release = Deploy("artifact") @ Production;
authorize release using discovered as armed;

observe evidence = "safe" from "fixture";
assess consensus = evidence with CollectiveReview;
op release = Deploy(evidence) @ Production;
authorize release using consensus as armed;

op plan = Plan("x") @ Production;
op release = Deploy("artifact") @ Production;
authorize release using plan as armed;

requires permit p: Deploy @ Production;
op release = Deploy("artifact") @ Production;
authorize release using p as armed;
commit armed as receipt;

requires permit p: Restart @ Production;
op release = Deploy("artifact") @ Production;
authorize release using p as armed;

requires permit p: Deploy @ Staging;
op release = Deploy("artifact") @ Production;
authorize release using p as armed;

requires permit p: Deploy @ Production;
op first = Deploy("a") @ Production;
op second = Deploy("b") @ Production;
authorize first using p as first_armed;
authorize second using p as second_armed;

requires prepared prior: Deploy @ Production;
cancel prior as canceled;
commit prior as receipt;

requires quorum gate: Deploy @ Production threshold 2 of Operator, Security, Provider;
op release = Deploy("artifact") @ Production;
authorize release using gate as armed;
